```

**动作处理：**

```303:308:c:\Users\win\Desktop\Agent Platform\prototype\10-skills-management.html
  function handleAction(id, act) {
    if (act === 'enable')      { Proto.updateSkillStatus(id, 'enabled');    Proto.toast('Skill 已启用'); renderList(id); refreshDrawerIfOpen(id); }
    else if (act === 'disable')    { Proto.updateSkillStatus(id, 'disabled');   Proto.toast('Skill 已停用'); renderList(id); refreshDrawerIfOpen(id); }
    else if (act === 'deprecate')  { Proto.updateSkillStatus(id, 'deprecated'); Proto.toast('Skill 已废弃，历史绑定保留'); renderList(id); refreshDrawerIfOpen(id); }
    else if (act === 'bump')       { var v = Proto.bumpSkillVersion(id); Proto.toast('已创建新版本 ' + (v && v.version)); renderList(id); refreshDrawerIfOpen(id); }
```

**状态更新逻辑**（内置 catalog 直接改内存；用户新建 skill 存 `sessionStorage`）：

```357:376:c:\Users\win\Desktop\Agent Platform\prototype\assets\proto.js
  function updateSkillStatus(id, status) {
    var list = getCustomSkills();
    var changed = null;
    list = list.map(function (s) {
      if (s.id !== id) return s;
      changed = Object.assign({}, s, { status: status, updatedAt: new Date().toISOString().slice(0, 10) });
      return changed;
    });
    setCustomSkills(list);
    if (!changed) {
      SKILL_CATALOG.forEach(function (s) {
        if (s.id === id) {
          s.status = status;
          s.updatedAt = new Date().toISOString().slice(0, 10);
          changed = s;
        }
      });
    }
    return changed || skillById(id);
  }
```

